private GeoPoint toMapPoint(double d, double d2) {
    if (!isGcjMap()) {
        return new GeoPoint(d, d2);
    }
    double[] dArrWgs84ToGcj02 = GeoUtils.wgs84ToGcj02(d2, d);
    return new GeoPoint(dArrWgs84ToGcj02[1], dArrWgs84ToGcj02[0]);
}
